<?php
require_once __DIR__ . '/includes/auth.php';require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../config/schema.php';require_once __DIR__ . '/../includes/functions.php';ensureFullSchema($pdo);$pageTitle='Clientes';$busca=trim($_GET['q']??'');
$sql="SELECT c.*, (SELECT COUNT(*) FROM pedidos p WHERE p.cliente_id=c.id) pedidos, (SELECT COUNT(*) FROM leituras l WHERE l.cliente_id=c.id) leituras FROM clientes c";$params=[];if($busca!==''){$sql.=" WHERE c.nome LIKE ? OR c.email LIKE ? OR c.telefone LIKE ?";$term='%'.$busca.'%';$params=[$term,$term,$term];}$sql.=" ORDER BY c.criado_em DESC";$st=$pdo->prepare($sql);$st->execute($params);$clientes=$st->fetchAll();
require __DIR__.'/includes/header.php';?>
<div class="admin-top"><div><span class="section-kicker">RELACIONAMENTO</span><h1>Clientes & perfis</h1><p>Uma base para atendimento, recompra e futuros conteúdos. O consentimento de marketing aparece separado para você não confundir cadastro com autorização de contato promocional.</p></div><?php if(($_SESSION['usuario_nivel']??'')==='admin'): ?><a class="btn btn-secondary" href="<?= BASE_URL ?>/admin/clientes-export.php">Exportar autorizados (.CSV)</a><?php endif; ?></div>
