<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Interesses</th><th>Marketing</th><th>Pedidos</th><th>Leituras</th><th>Desde</th></tr></thead><tbody><?php foreach($clientes as $c): ?><tr><td><strong><?= e($c['nome']) ?></strong><br><small><?= e($c['email']) ?><?= $c['telefone']?' · '.e($c['telefone']):'' ?></small></td><td><?= e($c['interesses']?:'Ainda não informou') ?></td><td><?= $c['aceita_marketing']?'<span class="status status-done">Autorizado</span>':'<span class="status status-new">Não autorizado</span>' ?></td><td><?= (int)$c['pedidos'] ?></td><td><?= (int)$c['leituras'] ?></td><td><?= date('d/m/Y',strtotime($c['criado_em'])) ?></td></tr><?php endforeach; ?></tbody></table></div>
